window.RP_SESSION={"id":"S-85abc95813f3","messages":[{"id":"RP-III-0078623","time":"2026-04-19T23:32:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"...\n...\n...","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078624","time":"2026-04-19T23:32:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"...!\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078625","time":"2026-04-19T23:33:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"아카쿠는 식은 땀을 흘리면서 잠에서 일어났다. 분명 1년은 지난 일임에도 그 기억이 떠오른다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078626","time":"2026-04-19T23:34:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"손을 바라본다. 노란색 비늘이 가득한 손등과 하얀색 손바닥. 푹신한 침대와 보드라운 이불. 옆에서 들려오는 규칙적인 숨소리.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078627","time":"2026-04-19T23:35:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"분명 끔찍한 기억이지만 공교롭게도 그 덕에 지금의 생활이 더욱 실감난다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078628","time":"2026-04-19T23:35:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"때는 1년 정도 된건가? 아카쿠와 미샤가 스카일라에서 골기아로 향하는 때. 아카쿠는 새로운 지역에 대한 여행이라는 생각에 잔뜩 들뜬 상태였다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078629","time":"2026-04-19T23:36:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"밖은 커녕 스카일라 외곽에도 가보지 않은 샌님이 바로 아카쿠를 이야기하는 것이리라.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078630","time":"2026-04-19T23:36:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"더워! 주변에 강이 없는 사막이 이렇게 더울줄이야!\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078631","time":"2026-04-19T23:38:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"아카쿠는 스카일라를 건너 로운델 남쪽을 슬쩍 경유한 뒤에 게일 사막을 건너고 있었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078632","time":"2026-04-19T23:39:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"저는 분명 석차를 몰자고 했어요. 아니면 낙타를 타는 것도 방법이에요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078633","time":"2026-04-19T23:41:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"사막의 낮은 덥고 햇볕이 아렸다. 온 몸을 감싸는 옷과 미샤가 주기적으로 뿌려주는 물이 없었다면 금방 쓰러졌을지도 모른다. 반면 사막의 밤은 매우 추웠다. 입에서 김이 나올 정도의 추위. 미샤를 감싸안고서 겨우 그 밤을 보냈다. 미샤가 드루이드라는 사실이 이렇게 고마울 수가 없었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078634","time":"2026-04-19T23:42:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"계속 짐만 되는 것 같아서 미안하네.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078635","time":"2026-04-19T23:42:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"제가 이것도 생각하지 못 했을까요?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078636","time":"2026-04-19T23:42:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"그래도...\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078637","time":"2026-04-19T23:42:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"아카쿠는 오해하는게 하나 있어요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078638","time":"2026-04-19T23:43:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"아카쿠는 제가 드루이드 교육을 받은 이후로 짐이 아니었던 적이 없어요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078639","time":"2026-04-19T23:43:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"너무한 이야기네!\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078640","time":"2026-04-19T23:43:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"힘들 때 옆에 있어줘. 문제가 생기면 같이 해결해. 심심하면 놀아줘. 그것 외에도..\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078641","time":"2026-04-19T23:44:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"...\"\n\n아카쿠는 그저 눈물을 속으로 삼키면서 미샤의 불평을 들을 수 밖에 없었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078642","time":"2026-04-19T23:44:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"그런 아카쿠의 모습을 보고 미샤는 아차! 너무 괴롭혔나? 싶었는지 목을 조금 가다듬고는...\n\n\"흠흠...\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078643","time":"2026-04-19T23:46:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"짐이라는게 결국은 모두에게 중요한거잖아요? 반려는 그런 존재라고 생각해요. 서로 좀 모자르다고 생각해도 같이 이끌어가고 서로 버팀목이 되어주고. 저도 분명 아카쿠가 저에게 필요한 존재라고 생각하니까 이렇게 있는거니까요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078644","time":"2026-04-19T23:46:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"뭔가 위로가 되는 것 같기도하고 아닌 것 같기도하고...\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078645","time":"2026-04-19T23:46:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"저는 그저... 스카일라 왕국에서 저를 혼자 두지 않았다는 것 만으로도 아카쿠에게 항상 고맙고 같이 있고 싶다는 생각을 하니까요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078646","time":"2026-04-19T23:47:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"그렇다면 다행이네. 하지만 반대로 생각하면... 우리가 그런 상황이 아니었다면 이렇게 같이 있을 일은 없다는 이야기 아니야?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078647","time":"2026-04-19T23:47:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"아...! 진짜 귀찮게 굴지 말아요!\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078648","time":"2026-04-19T23:48:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"미샤와 아카쿠가 이야기를 하는 사이에 멀리서 인기척이 느껴졌다. 아무도 없는 사막 미샤와 아카쿠가 피워둔 모닥불을 보고 찾아온 손님인가?","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078649","time":"2026-04-19T23:48:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"어... 누구십니까?\"\n\n아카쿠는 얼빠진 소리로 물어봤다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078650","time":"2026-04-19T23:49:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"어이쿠! 미안합니다! 밤 길을 걷는데 모닥불이 보여서 잠시...!\"\n\n불 넘어로 보이는 두명의 남성. 한 명은 몸집이 크지만 인상이 좋아보였고 다른 사람은 삐쭉 마르고 건강이 나빠보여 음침해 보였다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078651","time":"2026-04-19T23:51:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"이것 또한 카카투의 인도일지니! 넓은 사막에서 이렇게 만나게 되어 반갑습니다.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078652","time":"2026-04-19T23:51:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"미샤는 손님들이 찾아오자 후드로 얼굴을 가리고 일체 말을 하지 않고 있었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078653","time":"2026-04-19T23:52:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"거, 스카일라 분인가 봅니다.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078654","time":"2026-04-19T23:52:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"아시는군요? 아무래도 티가 많이 나겠죠?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078655","time":"2026-04-19T23:53:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"드라고니안에 카카투 신앙. 당연한 이야기 아니겠습니까?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078656","time":"2026-04-19T23:53:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"덩치가 크고 선한 인상의 사내는 제법 넉살이 좋은 사람이었다. 덕분에 아카쿠는 즐겁게 그와 대화를 이어갈 수 있었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078657","time":"2026-04-19T23:54:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"어이쿠! 혹시 식사는 하셨는가요? 모닥불도 이렇게 빌려쓰는데 염치가 없구만! 괜찮다면 제가 제법 솜씨가 좋은데 요깃거리라도 만들어도 되겠습니까?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078658","time":"2026-04-19T23:54:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"물론이요! 기대하겠습니다!\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078659","time":"2026-04-19T23:55:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"넉살 좋은 사내는 솥에 기름을 뿌리고는 이것저것 볶기 시작했다. 물이 귀한터라 기름을 대신하여 볶아낸 말린 식재료들은 기름을 먹어 제법 괜찮은 모습을 보인다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078660","time":"2026-04-19T23:56:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"다 된 것 같군요! 드셔보시지...\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078661","time":"2026-04-19T23:56:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"넉살 좋은 사내는 아카쿠에게 음식을 건내고 있었다. 곰으로 변한 미샤가 그의 머리를 날리기 전 까지는.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078662","time":"2026-04-19T23:57:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"미샤! 이게 무슨 짓이야!\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078663","time":"2026-04-19T23:57:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"갑작스레 사람이 죽었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078664","time":"2026-04-19T23:57:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"아카쿠는 믿을 수 없다는듯 미샤를 바라본다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078665","time":"2026-04-19T23:57:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"아카쿠. 바보같은 사람.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078666","time":"2026-04-19T23:58:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"어떻게하면 당신이 사람을 무서워할지 고민했어요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078667","time":"2026-04-19T23:58:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"덕분에 좋은 기회가 생겼네요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078668","time":"2026-04-19T23:58:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"미샤는 사람 모습으로 돌아온 후 냄새를 킁킁 맡으면서 살피더니 뚱뚱한 사람의 품에서 가죽 주머니에 들어있는 가루를 꺼내든다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078669","time":"2026-04-19T23:59:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"한 숟가락만 먹어도 거품을 물고 죽는 독약이에요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078670","time":"2026-04-19T23:59:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"아카쿠. 세상은 당신이 생각하는 것처럼 아름답지 않을거에요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078671","time":"2026-04-20T00:00:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"그렇게 말하면서 미샤는 옆에 있던 비쭉 마른 사람을 제압했다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078672","time":"2026-04-20T00:00:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"그러고서는 아카쿠에게 단검을 던졌다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078673","time":"2026-04-20T00:00:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"찔러요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078674","time":"2026-04-20T00:00:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"미샤... 이건 필요하지 않은 일이야.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078675","time":"2026-04-20T00:01:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"아니요, 필요해요. 그들은 분명 악인이에요. 만약 지금 이 자에게 자비를 베풀면 다음 희생양은 당신이 죽인 것이 되는거에요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078676","time":"2026-04-20T00:01:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"사람은 변해, 교화할 수 있어. 저도 그것은 알고 있어요. 하지만 생판 모르는 남을 위해 저희가 왜 그래야하죠?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078677","time":"2026-04-20T00:02:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"아카쿠는 혼란스러웠다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078678","time":"2026-04-20T00:02:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"사람을 죽이는 것은 분명 그릇된 행동이다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078679","time":"2026-04-20T00:02:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"라 엘라는 삶을 존중하라고 하셨다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078680","time":"2026-04-20T00:02:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"그 말은 생명을 소중하게 하라는 이야기. 다른 생명을 함부로 앗아가지 말라는 이야기.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078681","time":"2026-04-20T00:03:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"하지만 내가 여기서 이 자를 놓아준다면?","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078682","time":"2026-04-20T00:03:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"라 엘라는 죽은 자가 행복하게 떠날 수 있도록 도우라고 하셨다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078683","time":"2026-04-20T00:03:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"이는 죽은 자의 억울함을 풀어주라는 이야기.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078684","time":"2026-04-20T00:03:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"이 전에도 비슷한 방법으로 사람을 죽였을지도 모르는 일이다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078685","time":"2026-04-20T00:04:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"아카쿠는 단검을 주워들었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078686","time":"2026-04-20T00:04:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"떨리는 손으로 울먹이면서 조금씩 나아가는 단검은","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078687","time":"2026-04-20T00:04:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"비쩍 마른 사내의 가슴을 파고들었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078688","time":"2026-04-20T00:04:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"아카쿠는 그대로 뒤로 털썩 쓰러졌고 그런 아카쿠를 바라보면 미샤는 아카쿠를 감싸안고서 아무 말도 하지 않았다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078689","time":"2026-04-20T00:05:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"카카투시여... 저는 옳은 일을 한 것 입니까?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078690","time":"2026-04-20T00:06:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"손에 묻은 피는 없어지고 푹신한 침대, 부드러운 이불, 규칙적인 숨소리가 들려온다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078691","time":"2026-04-20T00:06:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"\"저는 잘 모르겠습니다. 세상은 아름답지만 또한 추악합니다.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078692","time":"2026-04-20T00:07:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"슬쩍 창문을 열고 하늘을 바라본다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078693","time":"2026-04-20T00:07:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"달이 밝다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078694","time":"2026-04-20T00:09:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"바슈르는 어머니와 같은 존재. 그녀는 지친 사람들을 감싸주지만 죄가 있다면 그 것을 뉘우칠 수 있도록 아이들을 인도한다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078695","time":"2026-04-20T00:09:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"아카쿠는 잠시 달을 보면서 기도를 올리고.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078696","time":"2026-04-20T00:09:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"다시 잠에 들었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078697","time":"2026-04-20T00:09:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"다만 아카쿠는 알고 있을까?","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078698","time":"2026-04-20T00:09:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"깨어 있던 것은 그 혼자만이 아니라는 사실을?","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078699","time":"2026-04-20T00:09:00+09:00","room":"RP III","name":"아카쿠 / 미샤","profile":"코난 발토르","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-III-0078700","time":"2026-04-20T00:09:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
